 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    # Each nonzero connected object consists of nested rectangular color bands.
    for sy in range(h):
        for sx in range(w):
            if grid[sy][sx] == 0 or (sy, sx) in seen:
                continue
            q = deque([(sy, sx)])
            seen.add((sy, sx))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))

            remaining = set(cells)
            bands = []
            while remaining:
                min_y = min(y for y, x in remaining)
                max_y = max(y for y, x in remaining)
                min_x = min(x for y, x in remaining)
                max_x = max(x for y, x in remaining)
                boundary = {(y, x) for y, x in remaining
                            if y in (min_y, max_y) or x in (min_x, max_x)}
                colors = {grid[y][x] for y, x in boundary}
                if len(colors) != 1:
                    # Not a uniform rectangular band; preserve rather than guess.
                    break
                color = next(iter(colors))
                if bands and bands[-1][0] == color:
                    bands[-1][1].update(boundary)
                else:
                    bands.append([color, set(boundary)])
                remaining.difference_update(boundary)

            if not remaining and bands:
                reversed_colors = [band[0] for band in reversed(bands)]
                for band, new_color in zip(bands, reversed_colors):
                    for y, x in band[1]:
                        out[y][x] = new_color
    return out
